import{_ as t,o,c as i,a3 as a}from"./chunks/framework.DX_KL3e0.js";const m=JSON.parse('{"title":"Tạo & giao công việc","description":"","frontmatter":{},"headers":[],"relativePath":"huong-dan/tao-cong-viec.md","filePath":"huong-dan/tao-cong-viec.md","lastUpdated":1782145431000}'),g={name:"huong-dan/tao-cong-viec.md"};function r(c,n,h,e,s,l){return o(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="tao-giao-cong-viec" tabindex="-1">Tạo &amp; giao công việc <a class="header-anchor" href="#tao-giao-cong-viec" aria-label="Permalink to &quot;Tạo &amp; giao công việc&quot;">​</a></h1><blockquote><p><strong>🎯 Mục tiêu:</strong> Tạo một đầu việc, giao cho người phụ trách và theo dõi tiến độ. <strong>👤 Ai làm được:</strong> Theo cấu hình quyền (thường Super Admin/Admin tạo &amp; giao; mọi người thấy việc liên quan đến mình). · <strong>⏱️ Khoảng:</strong> ~2 phút.</p></blockquote><h2 id="cac-buoc" tabindex="-1">Các bước <a class="header-anchor" href="#cac-buoc" aria-label="Permalink to &quot;Các bước&quot;">​</a></h2><ol><li>Vào <strong>Công Việc</strong> (nhóm <em>Hoạt Động</em>) → nhấn nút thêm công việc.</li><li>Điền: <ul><li><strong>Tiêu đề</strong> * (≥ 3 ký tự), <strong>Mô tả</strong>.</li><li><strong>Loại Công Việc</strong>, <strong>Độ Phức Tạp</strong>, <strong>Ưu Tiên</strong>, <strong>Trạng Thái</strong>.</li><li><strong>Người phụ trách</strong> * — mặc định là bạn; chọn người khác để <strong>giao việc</strong>.</li><li><strong>Ngày Bắt Đầu</strong> &amp; <strong>Hạn Chót</strong> (hạn chót phải sau ngày bắt đầu, không nằm trong quá khứ).</li></ul></li><li>Nhấn lưu.</li></ol><h2 id="✅-ket-qua" tabindex="-1">✅ Kết quả <a class="header-anchor" href="#✅-ket-qua" aria-label="Permalink to &quot;✅ Kết quả&quot;">​</a></h2><p>Công việc hiện trên bảng (<strong>Kanban / Lịch / Gantt / Lưới</strong>). Người phụ trách nhận thông báo.</p><h2 id="💡-meo-luu-y" tabindex="-1">💡 Mẹo &amp; lưu ý <a class="header-anchor" href="#💡-meo-luu-y" aria-label="Permalink to &quot;💡 Mẹo &amp; lưu ý&quot;">​</a></h2><ul><li>Chia nhỏ: mở chi tiết công việc → thêm <strong>công việc con</strong>.</li><li>Nhiều người cùng làm: 1 <strong>người phụ trách</strong> chính + thêm <strong>người thực hiện bổ sung</strong>; người khác <strong>Theo dõi</strong> để nhận cập nhật.</li><li>Cập nhật tiến độ: đổi <strong>Trạng Thái</strong> hoặc kéo-thả trên <strong>Kanban</strong>.</li></ul><p><em>Chi tiết: <a href="/help/chuc-nang/cong-viec.html">Công Việc</a></em></p>',9)])])}const p=t(g,[["render",r]]);export{m as __pageData,p as default};
